package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.hq.app.voidreason.VoidReasonStore;
import net.officefloor.hq.app.watch.WatchStore;
import net.officefloor.plugin.variable.Val;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Settles each selected claim, in list order: its people in the order they were added, a person's
 *  claims newest first. Each goes through the very steps of a single settle by the user (period,
 *  clerk limit, opened-by and status checks, then store, log and audit), so a clerk's settle above
 *  the clerk limit sends it to PENDING, which counts as settled. A claim that is not on the sheet,
 *  or that a single settle would refuse (every claim on an archived sheet), is refused and left as it is. */
public class SettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettleInput input, ClaimStore store,
            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, RoleStore roles,
            RateStore rates, ClaimLogStore log, RollupService rollups, Audit audit, WatchStore watches,
            VoidReasonStore voidReasons,
            Out<BulkSettleResult> result) {
        String sheet = sheetId.trim();
        Map<Long, Integer> personOrder = new HashMap<>();
        for (Person person : people.list(sheet)) {
            personOrder.put(person.getId(), personOrder.size());
        }
        int refused = 0;
        List<Claim> selected = new ArrayList<>();
        for (Long id : input.claimIds()) {
            Claim claim = id == null ? null : store.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                .thenComparing(Comparator.comparingLong(Claim::getId).reversed()));
        StatusInput status = new StatusInput(ClaimStatus.SETTLED, input.user(), false, "");
        int settled = 0;
        for (Claim claim : selected) {
            try {
                sheets.refuseArchived(sheet);
                new CheckClaimPeriod().check(claim, periods);
                StatusMove[] move = new StatusMove[1];
                new CheckClerkLimit().check(status, claim, roles, settings, people, rates, sheets, store, log,
                        m -> move[0] = m);
                Rollup before = rollups.snapshot(sheet);
                StatusChange[] change = new StatusChange[1];
                new ApplyStatus().apply(status, move[0], claim, store, people, rates, settings, sheets, periods, voidReasons,
                        c -> change[0] = c);
                new SaveClaim().save(status, claim, store, log);
                new AuditClaimStatus().audit(status, move[0], claim, change[0], before, people, audit, rollups, watches);
                settled++;
            } catch (InvalidSheetException e) {
                refused++;
            }
        }
        result.set(new BulkSettleResult(settled, refused));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Freezes the SETTLED claim again at the due it would have today as an OPEN claim bound by no
 *  statement: its person's grade rate in force on its date, rounded as the sheet's policy date has
 *  it, plus the late charge it would have now, and at least the sheet's floor (none for a correction).
 *  Stores it and logs a SETTLED line, by the user; refused when another user moved it on first. */
public class ApplyResettle {
    public void apply(@Val ResettleInput input, @Val Claim claim, ClaimStore store, ClaimLogStore log,
            PersonStore people, RateStore rates, SettingStore settings, SheetStore sheets,
            Out<Resettlement> resettlement) throws InvalidSheetException {
        if (!store.move(claim, ClaimStatus.SETTLED, ClaimStatus.SETTLED)) {
            throw new InvalidSheetException("Only a SETTLED claim can be re-settled");
        }
        String sheetId = claim.getSheetId();
        Claim open = new Claim(claim.getId(), sheetId, claim.getPersonId(), claim.getAmount(), claim.getDate(),
                claim.getNote(), ClaimStatus.OPEN, claim.getNumber(), null, claim.getOpenedBy(), false, null,
                claim.getCorrects(), claim.getDueBy());
        Person person = people.find(sheetId, claim.getPersonId());
        BigDecimal pct = person == null ? null : rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal now = Lateness.of(sheetId, settings, sheets, store, people).due(open, pct);
        BigDecimal old = claim.getSettledDue();
        claim.setSettledDue(now);
        store.save(claim);
        log.record(claim, input.user());
        resettlement.set(new Resettlement(old, now));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayStore;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Splits the amount off the OPEN claim, which keeps the rest unbound from any statement figure, into a new
 *  OPEN claim of the same date and note, numbered next in the period of its own due-by (see {@link Numbering}), opened by the user, due by
 *  the business day its person's own terms (else their grade's in force on that date, else the sheet's then) after its date, fixed
 *  now (a late entry when the period that due-by falls in is soft-closed), and logged as OPEN by the user. Refused when another user moved the claim on first. */
public class ApplySplit {
    public void apply(@Val SplitInput input, @Val Claim claim, ClaimStore store, PersonStore people, SettingStore settings,
            SheetStore sheets, PeriodStore periods, ClaimLogStore log, HolidayStore holidays,
            Out<Split> split) throws InvalidSheetException {
        if (!store.shrink(claim, claim.getAmount().subtract(input.amount()))) {
            throw new InvalidSheetException("Only an OPEN claim can be split");
        }
        String sheetId = claim.getSheetId();
        Person person = people.find(sheetId, claim.getPersonId());
        LocalDate dueBy = ClaimPeriods.dueByOf(person, claim.getDate(), settings, holidays);
        String number = Numbering.next(sheetId, dueBy, store, settings, sheets, periods);
        Claim into = store.addSplit(claim, input.amount(), number, input.user(), dueBy);
        if (periods.softOn(sheetId, dueBy)) {
            store.markLateEntry(into);
        }
        log.record(into, input.user());
        split.set(new Split(into));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.History;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims kept per sheet, newest first: by when each was added, or moved to its person. */
@Repository
public class ClaimStore {

    private static final RowMapper<Claim> ROW = (rs, i) -> {
        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"),
            rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getObject("claim_date", LocalDate.class),
            rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
            rs.getString("number"), rs.getBigDecimal("settled_due"),
            rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"),
            rs.getString("corrects"), rs.getObject("due_by", LocalDate.class));
        claim.setStatedNa(rs.getBoolean("stated_na"));
        claim.setDeferredUntil(rs.getObject("deferred_until", LocalDate.class));
        claim.setProofs(rs.getInt("proofs"));
        claim.setSplitFrom(rs.getString("split_from"));
        claim.setLateEntry(rs.getBoolean("late_entry"));
        claim.setRemindedOn(rs.getObject("reminded_on", LocalDate.class));
        claim.setRef(rs.getString("ref"));
        claim.setTags(rs.getString("tags"));
        claim.setVoidReason(rs.getString("void_reason"));
        return claim;
    };

    private final JdbcTemplate jdbc;

    public ClaimStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Claim> list(String sheetId) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY listed DESC", ROW, sheetId);
    }

    /** The sheet's claims as they stood at the end of the date (see {@link History}), newest first. */
    public List<Claim> listAsOf(String sheetId, LocalDate date) {
        return jdbc.query("SELECT * FROM " + History.asOf("claim", "id", date) + " WHERE sheet_id = ? ORDER BY listed DESC",
                ROW, sheetId);
    }

    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person's claim with the number, or null when they have none. */
    public Claim findByNumber(String sheetId, long personId, String number) {
        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ?", ROW,
                sheetId, personId, number);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Every tag ever carried by a claim on the sheet (by its history, see {@link History}), as stored (see
     *  {@link Tags}); up to the end of {@code date} when given, else up to now. */
    public List<String> tagsEverUsed(String sheetId, LocalDate date) {
        return date == null
                ? jdbc.queryForList("SELECT DISTINCT tags FROM claim_hist WHERE sheet_id = ? AND tags IS NOT NULL "
                        + "UNION SELECT DISTINCT tags FROM claim WHERE sheet_id = ? AND tags IS NOT NULL",
                        String.class, sheetId, sheetId)
                : jdbc.queryForList("SELECT DISTINCT tags FROM claim_hist WHERE sheet_id = ? AND tags IS NOT NULL "
                        + "AND hist_made_on <= ?", String.class, sheetId, Date.valueOf(date));
    }

    /** Whether a claim on the sheet other than {@code exceptId} carries the reference, compared without regard to case. */
    public boolean refTaken(String sheetId, String ref, long exceptId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND LOWER(ref) = LOWER(?) AND id <> ?",
                Integer.class, sheetId, ref, exceptId);
        return n != null && n > 0;
    }

    /** Adds a draft claim due by {@code dueBy}, which stays as it is whatever later changes. */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy) {
        return add(sheetId, personId, amount, date, note, corrects, dueBy, null);
    }

    /** Adds a draft claim due by {@code dueBy} with the external reference (null for none). */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy, String ref) {
        return add(sheetId, personId, amount, date, note, corrects, dueBy, ref, null);
    }

    /** Adds a draft claim due by {@code dueBy} with the external reference and tags (null for none). */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy, String ref, String tags) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, ref, tags) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "ID" });
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            ps.setString(6, corrects);
            ps.setDate(7, Date.valueOf(dueBy));
            ps.setString(8, ref);
            ps.setString(9, tags);
            return ps;
        }, keys);
        Claim added = new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null,
                false, null, corrects, dueBy);
        added.setRef(ref);
        added.setTags(tags);
        return added;
    }

    /** Marks the added claim a late entry: added while the period its due-by falls in was soft-closed. */
    public void markLateEntry(Claim claim) {
        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet_id = ? AND id = ?", claim.getSheetId(), claim.getId());
        claim.setLateEntry(true);
    }

    public void save(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, settled_due = ?, opened_by = ?, void_reason = ? "
                + "WHERE sheet_id = ? AND id = ?",
                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
                claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.getVoidReason(), claim.getSheetId(), claim.getId());
    }

    /** Stores a draft's amount, date, note, the claim it corrects and its reference and its tags, releasing its lock; false when the stored claim is no longer a draft. */
    public boolean edit(Claim claim) {
        return jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, corrects = ?, ref = ?, tags = ?, locked_by = NULL WHERE sheet_id = ? AND id = ? AND status = ?",
                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getCorrects(), claim.getRef(), claim.getTags(), claim.getSheetId(), claim.getId(),
                ClaimStatus.DRAFT.name()) == 1;
    }
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's claim on a sheet. {@code amount} has two decimals and is 0.00 or more, or negative for
 *  a correction, which names the number of the settled claim of its person it corrects; it starts
 *  as {@link ClaimStatus#DRAFT}. */
public class Claim {
    private final long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private boolean statedNa;
    private String corrects;
    private final LocalDate dueBy;
    private LocalDate deferredUntil;
    private int proofs;
    private String splitFrom;
    private boolean lateEntry;
    private LocalDate remindedOn;
    private String ref;
    private String tags;
    private String voidReason;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
            BigDecimal statedDue, String corrects, LocalDate dueBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
        this.corrects = corrects;
        this.dueBy = dueBy;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public LocalDate getDate() { return date; }
    public String getNote() { return note; }
    public ClaimStatus getStatus() { return status; }
    /** The number given when the claim was opened (the sheet-wide 1, 2, ..., or <period>-<n> / X-<n>
     *  while the sheet numbers by period); null for a draft, or a claim voided as a draft;
     *  a claim voided once open keeps it. */
    public String getNumber() { return number; }
    /** The due fixed when the claim was settled; null when not settled, or settled with no rate. */
    public BigDecimal getSettledDue() { return settledDue; }
    /** The user who opened the claim; null until it is opened. */
    public String getOpenedBy() { return openedBy; }
    /** Whether the person's last statement bound the claim to its figure then. */
    public boolean isStated() { return stated; }
    /** The figure the claim was bound to by the person's last statement; null when it had none (n/a)
     *  or is not bound. */
    public BigDecimal getStatedDue() { return statedDue; }
    /** Whether the person's last statement bound the claim to n/a: the rate that would apply to it had
     *  ended (its to-date) before the claim's date. */
    public boolean isStatedNa() { return statedNa; }
    /** Whether the claim keeps the figure its person's last statement bound it to (a figure, or n/a when
     *  {@link #isStatedNa()}): not while it is PENDING, when it follows its live figure (it is bound
     *  again if rejected back to OPEN). */
    public boolean isBound() { return stated && (statedDue != null || statedNa) && status != ClaimStatus.PENDING; }
    /** The number of the claim this correction corrects; null when it is not a correction. */
    public String getCorrects() { return corrects; }
    /** Whether the claim is a correction: a negative amount, with no floor and no late charge. */
    /** The date the claim is due by, fixed when it was added; later changes to the terms or its date
     *  leave it as it is. */
    public LocalDate getDueBy() { return dueBy; }
    public boolean isCorrection() { return amount.signum() < 0; }
    /** The date the claim was last deferred until; null when it was never deferred. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    /** Whether the claim is deferred on {@code today}: OPEN and deferred until a date after it. Until
     *  then it counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }
    /** How many proofs the claim has; a claim due above the sheet's proof threshold on its date cannot be
     *  settled or approved while it has none (see {@link CheckProofs}). */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }
    /** The number of the claim this claim was split off; null when it was not split off another. */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }
    /** Whether the claim was added while the period its due-by falls in was soft-closed. */
    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }
    /** The last sheet's today a reminder was written for the claim; null when it was never reminded. */
    public LocalDate getRemindedOn() { return remindedOn; }
    public void setRemindedOn(LocalDate remindedOn) { this.remindedOn = remindedOn; }
    /** The external reference, unique on the sheet without regard to case; null when it has none. */
    public String getRef() { return ref; }
    public void setRef(String ref) { this.ref = ref; }
    /** Its tags (see {@link Tags}): sorted, comma separated; null when it has none. */
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }
    /** The reason it was voided with, from the sheet's list then; null when not voided, or voided while the list was empty. */
    public String getVoidReason() { return voidReason; }
    public void setVoidReason(String voidReason) { this.voidReason = voidReason; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    public void setPersonId(long personId) { this.personId = personId; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public void setDate(LocalDate date) { this.date = date; }
    public void setNote(String note) { this.note = note; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    public void setNumber(String number) { this.number = number; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    public void setStated(boolean stated) { this.stated = stated; }
    public void setStatedDue(BigDecimal statedDue) { this.statedDue = statedDue; }
    public void setStatedNa(boolean statedNa) { this.statedNa = statedNa; }
}
