# PUT /api/sheets/{sheetId}/claims/{claimId} — edit a draft claim's amount, date, note, ref, tags and the
# claim it corrects (body as an add; a correction is checked as on an add). Refused (400) like an add, when the claim is not on the sheet, when it is not a DRAFT
# (an open claim is voided and added anew instead), or
# when another user has locked it by opening its editor, when its due-by (fixed when it was added, so left as it is by an edit) falls in a closed period, or when its new date is after the date
# its person is retired from, or when its ref is one another claim on the sheet carries; nothing is stored then.
# A stored change releases the claim's lock and is recorded in the audit file as CLAIM_EDITED; a refused one records nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkLock
checkLock:
  class: net.officefloor.hq.app.claim.CheckClaimLock
  govern: [ transaction ]
  next: checkDraft
checkDraft:
  class: net.officefloor.hq.app.claim.CheckClaimDraft
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: checkRetired
checkRetired:
  class: net.officefloor.hq.app.claim.CheckClaimRetired
  govern: [ transaction ]
  next: checkCorrection
checkCorrection:
  class: net.officefloor.hq.app.claim.CheckClaimCorrection
  govern: [ transaction ]
  next: checkRef
checkRef:
  class: net.officefloor.hq.app.claim.CheckClaimRef
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimEdit
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimEdited
